class RestoreOptionsView extends ConsumerStatefulWidget {
  const RestoreOptionsView({
    super.key,
    required this.walletName,
    required this.coin,
  });

  static const routeName = "/restoreOptions";

  final String walletName;
  final CryptoCurrency coin;

  @override
  ConsumerState<RestoreOptionsView> createState() => _RestoreOptionsViewState();
}

class _RestoreOptionsViewState extends ConsumerState<RestoreOptionsView> {
  late final String walletName;
  late final CryptoCurrency coin;
  late final bool isDesktop;

  late FocusNode textFieldFocusNode;
  late final FocusNode passwordFocusNode;
  late final TextEditingController passwordController;
  late final StartHeightPickerController _heightController;

  bool hidePassword = true;

  @override
  void initState() {
    super.initState();
    walletName = widget.walletName;
    coin = widget.coin;
    isDesktop = Util.isDesktop;

    textFieldFocusNode = FocusNode();
    passwordController = TextEditingController();
    passwordFocusNode = FocusNode();
    _heightController = StartHeightPickerController();
  }

  @override
  void dispose() {
    textFieldFocusNode.dispose();
    passwordController.dispose();
    passwordFocusNode.dispose();
    _heightController.dispose();
    super.dispose();
  }

  // 0 = Seed, 1 = View Only, 2 = URI (Monero only)
  int _restoreMode = 0;
  WalletUriData? _uriData;

  bool _nextLock = false;
  Future<void> nextPressed() async {
    if (_nextLock) return;
    _nextLock = true;
    try {
      if (!isDesktop) {
        // hide keyboard if has focus
        if (FocusScope.of(context).hasFocus) {
          FocusScope.of(context).unfocus();
          await Future<void>.delayed(const Duration(milliseconds: 75));
        }
      }

      if (mounted) {
        final int height = _heightController.height;
        switch (_restoreMode) {
          case 0: // Seed
            await Navigator.of(context).pushNamed(
              RestoreWalletView.routeName,
              arguments: Tuple5(
                walletName,
                coin,
                ref.read(mnemonicWordCountStateProvider.state).state,
                height,
                passwordController.text,
              ),
            );
            break;
          case 1: // View Only
            await Navigator.of(context).pushNamed(
              RestoreViewOnlyWalletView.routeName,
              arguments: (
                walletName: walletName,
                coin: coin,
                restoreBlockHeight: height,
              ),
            );
            break;
          case 2: // URI
            await _attemptUriRestore(height);
            break;
        }
      }
    } finally {
      _nextLock = false;
    }
  }

  Future<void> _attemptUriRestore(int fallbackHeight) async {
    final data = _uriData;
    if (data == null) return;

    if (!isDesktop) {
      FocusScope.of(context).unfocus();
      await Future<void>.delayed(const Duration(milliseconds: 100));
    }

    if (!mounted) return;

    await showDialog<dynamic>(
      context: context,
      useSafeArea: false,
      barrierDismissible: true,
      builder: (context) {
        return ConfirmRecoveryDialog(
          onConfirm: () => _doUriRestore(data, fallbackHeight),
        );
      },
    );
  }

  Future<void> _doUriRestore(WalletUriData data, int fallbackHeight) async {
    if (!Platform.isLinux && !isDesktop) await WakelockPlus.enable();

    final restoreHeight = data.height ?? fallbackHeight;

    try {
      final Map<String, dynamic> otherDataJson;
      if (data.seed != null) {
        otherDataJson = {};
      } else if (data.isViewOnly) {
        otherDataJson = {
          WalletInfoKeys.isViewOnlyKey: true,
          WalletInfoKeys.viewOnlyTypeIndexKey:
              ViewOnlyWalletType.cryptonote.index,
        };
      } else {
        otherDataJson = {WalletInfoKeys.isRestoredFromKeysKey: true};
      }

      final info = WalletInfo.createNew(
        coin: coin,
        name: walletName,
        restoreHeight: restoreHeight,
        otherDataJsonString: jsonEncode(otherDataJson),
      );

      bool isRestoring = true;
      if (mounted) {
        unawaited(
          showDialog<dynamic>(
            context: context,
            useSafeArea: false,
            barrierDismissible: false,
            builder: (context) {
              return RestoringDialog(
                onCancel: () async {
                  isRestoring = false;
                  await ref
                      .read(pWallets)
                      .deleteWallet(info, ref.read(secureStoreProvider));
                },
              );
            },
          ),
        );
      }

      try {
        var node = ref
            .read(nodeServiceChangeNotifierProvider)
            .getPrimaryNodeFor(currency: coin);

        if (node == null) {
          node = coin.defaultNode(isPrimary: true);
          await ref
              .read(nodeServiceChangeNotifierProvider)
              .save(node, null, false);
        }

        final Wallet wallet;
        if (data.seed != null) {
          wallet = await Wallet.create(
            walletInfo: info,
            mainDB: ref.read(mainDBProvider),
            secureStorageInterface: ref.read(secureStoreProvider),
            nodeService: ref.read(nodeServiceChangeNotifierProvider),
            prefs: ref.read(prefsChangeNotifierProvider),
            mnemonic: data.seed,
          );
        } else if (data.isViewOnly) {
          final viewOnlyData = CryptonoteViewOnlyWalletData(
            walletId: info.walletId,
            address: data.address ?? "",
            privateViewKey: data.viewKey!,
          );
          wallet = await Wallet.create(
            walletInfo: info,
            mainDB: ref.read(mainDBProvider),
            secureStorageInterface: ref.read(secureStoreProvider),
            nodeService: ref.read(nodeServiceChangeNotifierProvider),
            prefs: ref.read(prefsChangeNotifierProvider),
            viewOnlyData: viewOnlyData,
          );
        } else {
          final keysRestoreData = jsonEncode({
            "address": data.address ?? "",
            "viewKey": data.viewKey!,
            "spendKey": data.spendKey!,
          });
          wallet = await Wallet.create(
            walletInfo: info,
            mainDB: ref.read(mainDBProvider),
            secureStorageInterface: ref.read(secureStoreProvider),
            nodeService: ref.read(nodeServiceChangeNotifierProvider),
            prefs: ref.read(prefsChangeNotifierProvider),
            keysRestoreData: keysRestoreData,
          );
        }

        if (wallet is CryptonoteWallet) {
          await wallet.init(isRestore: true);
        } else {
          await wallet.init();
        }

        await wallet.recover(isRescan: false);

        if (mounted) {
          await wallet.info.setMnemonicVerified(
            isar: ref.read(mainDBProvider).isar,
          );

          if (ref.read(pDuress)) {
            await wallet.info.updateDuressVisibilityStatus(
              isDuressVisible: true,
              isar: ref.read(mainDBProvider).isar,
            );
          }

          ref.read(pWallets).addWallet(wallet);

          if (mounted) {
            if (isDesktop) {
              Navigator.of(
                context,
              ).popUntil(ModalRoute.withName(DesktopHomeView.routeName));
            } else {
              unawaited(
                Navigator.of(
                  context,
                ).pushNamedAndRemoveUntil(HomeView.routeName, (route) => false),
              );
            }

            await showDialog<dynamic>(
              context: context,
              useSafeArea: false,
              barrierDismissible: true,
              builder: (context) => const RestoreSucceededDialog(),
            );
          }
        }
      } catch (e) {
        if (mounted && isRestoring) {
          Navigator.pop(context);
          await showDialog<dynamic>(
            context: context,
            useSafeArea: false,
            barrierDismissible: true,
            builder: (context) => RestoreFailedDialog(
              errorMessage: e.toString(),
              walletId: info.walletId,
              walletName: info.name,
            ),
          );
        }
      }
    } finally {
      if (!Platform.isLinux && !isDesktop) await WakelockPlus.disable();
    }
  }

  Future<void> chooseMnemonicLength() async {
    await showModalBottomSheet<dynamic>(
      backgroundColor: Colors.transparent,
      context: context,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (_) {
        return MnemonicWordCountSelectSheet(
          lengthOptions: coin.possibleMnemonicLengths,
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType with ${coin.identifier} $walletName");

    return MasterScaffold(
      isDesktop: isDesktop,
      appBar: isDesktop
          ? const DesktopAppBar(
              isCompactHeight: false,
              leading: AppBarBackButton(),
              trailing: ExitToMyStackButton(),
            )
          : AppBar(
              leading: AppBarBackButton(
                onPressed: () {
                  if (textFieldFocusNode.hasFocus) {
                    textFieldFocusNode.unfocus();
                    Future<void>.delayed(
                      const Duration(milliseconds: 100),
                    ).then((value) => Navigator.of(context).pop());
                  } else {
                    Navigator.of(context).pop();
                  }
                },
              ),
            ),
      body: RestoreOptionsPlatformLayout(
        isDesktop: isDesktop,
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxWidth: isDesktop ? 480 : double.infinity,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Spacer(flex: isDesktop ? 10 : 1),
              if (!isDesktop) CoinImage(coin: coin, height: 100, width: 100),
              SizedBox(height: isDesktop ? 0 : 16),
              Text(
                "Restore options",
                textAlign: TextAlign.center,
                style: isDesktop
                    ? STextStyles.desktopH2(context)
                    : STextStyles.pageTitleH1(context),
              ),
              SizedBox(height: isDesktop ? 40 : 24),
              if (coin is ViewOnlyOptionCurrencyInterface)
                SizedBox(
                  height: isDesktop ? 56 : 48,
                  width: isDesktop ? 490 : null,
                  child: coin is Monero
                      ? Options(
                          key: UniqueKey(),
                          texts: const ["Seed", "View Only", "URI"],
                          onColor: Theme.of(
                            context,
                          ).extension<StackColors>()!.popupBG,
                          offColor: Theme.of(
                            context,
                          ).extension<StackColors>()!.textFieldDefaultBG,
                          selectedIndex: _restoreMode,
                          onValueChanged: (value) {
                            setState(() {
                              _restoreMode = value;
                            });
                          },
                          decoration: BoxDecoration(
                            color: Colors.transparent,
                            borderRadius: BorderRadius.circular(
                              Constants.size.circularBorderRadius,
                            ),
                          ),
                        )
                      : Toggle(
                          key: UniqueKey(),
                          onText: "Seed",
                          offText: "View Only",
                          onColor: Theme.of(
                            context,
                          ).extension<StackColors>()!.popupBG,
                          offColor: Theme.of(
                            context,
                          ).extension<StackColors>()!.textFieldDefaultBG,
                          isOn: _restoreMode == 1,
                          onValueChanged: (value) {
                            setState(() {
                              _restoreMode = value ? 1 : 0;
                            });
                          },
                          decoration: BoxDecoration(
                            color: Colors.transparent,
                            borderRadius: BorderRadius.circular(
                              Constants.size.circularBorderRadius,
                            ),
                          ),
                        ),
                ),
              if (coin is ViewOnlyOptionCurrencyInterface)
                SizedBox(height: isDesktop ? 40 : 24),
              if (_restoreMode == 1)
                ViewOnlyRestoreOption(
                  coin: coin,
                  heightController: _heightController,
                )
              else if (_restoreMode == 2)
                UriRestoreOption(
                  coin: coin,
                  heightController: _heightController,
                  onParsed: (data) => setState(() => _uriData = data),
                )
              else
                SeedRestoreOption(
                  coin: coin,
                  heightController: _heightController,
                  pwController: passwordController,
                  pwFocusNode: passwordFocusNode,
                  chooseMnemonicLength: chooseMnemonicLength,
                ),
              if (!isDesktop) const Spacer(flex: 3),
              SizedBox(height: isDesktop ? 32 : 12),
              ListenableBuilder(
                listenable: _heightController,
                builder: (context, _) => RestoreOptionsNextButton(
                  isDesktop: isDesktop,
                  onPressed: _restoreMode == 2
                      ? (_uriData != null ? nextPressed : null)
                      : (_heightController.canProceed ? nextPressed : null),
                ),
              ),
              if (isDesktop) const Spacer(flex: 15),
            ],
          ),
        ),
      ),
    );
  }
}

